import{H as e,_t as t,it as n,rt as r}from"./chunks/framework.Bcve9O8f.js";var i=JSON.parse(`{"title":"SDK","description":"The deposit's quantum theorems on a ZFS-shaped content-address substrate, carrying cross-encrypted UUID streams — unbounded capacity, verified by handle.","frontmatter":{"title":"SDK","description":"The deposit's quantum theorems on a ZFS-shaped content-address substrate, carrying cross-encrypted UUID streams — unbounded capacity, verified by handle.","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"SDK | Millennium Solutions"}],["meta",{"property":"og:description","content":"The deposit's quantum theorems on a ZFS-shaped content-address substrate, carrying cross-encrypted UUID streams — unbounded capacity, verified by handle."}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/sdk.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"SDK | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"The deposit's quantum theorems on a ZFS-shaped content-address substrate, carrying cross-encrypted UUID streams — unbounded capacity, verified by handle."}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/sdk.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/sdk.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/sdk.html"}]]},"headers":[],"relativePath":"sdk.md","filePath":"sdk.md"}`),a={name:`sdk.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="the-sdk-—-two-legs-one-shape" tabindex="-1">The SDK — two legs, one shape <a class="header-anchor" href="#the-sdk-—-two-legs-one-shape" aria-label="Permalink to “The SDK — two legs, one shape”">​</a></h1><blockquote><p>The SDK stands on two legs that are the <strong>same content-address shape</strong> at two levels: the <strong>theorems</strong> (this deposit&#39;s kernel-checked math) and the <strong>substrate</strong> (a ZFS-shaped content-address store). Between them run <strong>cross-encrypted UUID streams</strong>. Everything below is sealed or measured; the one quantum-<em>device</em> claim is marked open, with its path.</p></blockquote><h2 id="the-substrate-—-zfs-is-the-content-address-shape-in-the-kernel" tabindex="-1">The substrate — ZFS is the content-address shape in the kernel <a class="header-anchor" href="#the-substrate-—-zfs-is-the-content-address-shape-in-the-kernel" aria-label="Permalink to “The substrate — ZFS is the content-address shape in the kernel”">​</a></h2><p>The deposit builds content-addressing in software; <strong>ZFS already is it</strong> at the filesystem level. The correspondence is sealed (8 theorems, receipts <code>06d8923a-470b</code>, <code>f3365bad-fbc7…</code>):</p><table tabindex="0"><thead><tr><th>deposit primitive</th><th>ZFS feature</th><th>shared shape</th></tr></thead><tbody><tr><td><code>toUuid</code> / content-address</td><td>block <strong>checksum</strong></td><td>address</td></tr><tr><td><code>merkleFold</code> / seal root</td><td><strong>block-pointer merkle tree</strong> (uberblock)</td><td>merkle</td></tr><tr><td>handle cache (verify-by-handle)</td><td><strong>dedup + ARC</strong></td><td>cache</td></tr><tr><td>the <strong>304 involution</strong> (serve, not recompute)</td><td><strong>copy-on-write</strong> snapshots/clones</td><td>involution</td></tr><tr><td>UUID</td><td>pool/dataset <strong>GUID</strong></td><td>guid</td></tr><tr><td><code>recompute</code> / scrub</td><td><strong>scrub</strong> (recompute &amp; check)</td><td>verify</td></tr></tbody></table><p><strong>The efficiency both legs get, sealed:</strong> a state is <em>verified</em> in <strong>one step</strong> (read the address) where <em>recompute</em> re-runs all <strong>n</strong> facts — so <code>verify(1) &lt; recompute(n)</code> for every n ≥ 2, the advantage <code>n−1</code> unbounded. This is why <strong>caching via handles removes the memory wall</strong>: generation is paid once and committed; from then on the pipeline only verifies by handle (the ECPP certificates for 2^999+1 are exactly this — generated once at 8 GB, re-verified cheaply).</p><h2 id="the-streams-—-cross-encrypted-uuid-unbounded-capacity" tabindex="-1">The streams — cross-encrypted UUID, unbounded capacity <a class="header-anchor" href="#the-streams-—-cross-encrypted-uuid-unbounded-capacity" aria-label="Permalink to “The streams — cross-encrypted UUID, unbounded capacity”">​</a></h2><p>Each UUID is a 128-bit register (sealed, 21 capacity theorems, receipts <code>05ee2cb9-0963</code>, <code>9c0e2abe-7301…</code>): <strong>6 reserved</strong> (the hexbit coil), <strong>122 free</strong>. Cross-encrypting the version nibble reclaims 4 — only the <strong>2-bit variant</strong> is irreducible — so <strong>122 → 126</strong> addressable bits per stream. Read as the teleport grain, two classical bits signal one primitive: <strong>61 primitives per UUID</strong> (⌊122/2⌋).</p><p><strong>Unbounded by streams, not by one register.</strong> ZFS stores unboundedly many such streams; each is deduped, snapshotted and scrubbed by checksum, and verified by its handle in O(1) regardless of how many there are. So the <em>encoding</em> capacity is unbounded in the number of streams, and the Mermin advantage is proved for <strong>every</strong> width (15 octave theorems) — the quantum <em>shape</em> is uncapped.</p><h2 id="the-theorems-—-the-math-leg" tabindex="-1">The theorems — the math leg <a class="header-anchor" href="#the-theorems-—-the-math-leg" aria-label="Permalink to “The theorems — the math leg”">​</a></h2><ul><li><strong>2^999+1 FULLY PROVED FACTORED</strong> — every factor proved prime (deposit deterministic test + APR-CL), with portable ECPP certificates (/iso-conformance, evidence/factor/).</li><li><strong>Mermin lead proved for every width</strong> — 15 theorems; the advantage <code>2^(k-1)</code> gains an exponent each octave without bound.</li><li><strong>the quantum-computer status</strong> — a value <code>complete | incomplete | refuted</code> (40 theorems), currently <strong>incomplete</strong>: design complete, device open.</li></ul><h2 id="honest-floor-—-what-unlimited-quantum-capacity-means-here" tabindex="-1">Honest floor — what &quot;unlimited quantum capacity&quot; means here <a class="header-anchor" href="#honest-floor-—-what-unlimited-quantum-capacity-means-here" aria-label="Permalink to “Honest floor — what &quot;unlimited quantum capacity&quot; means here”">​</a></h2><p>The capacity is <strong>encoding</strong> capacity — unbounded UUID streams on a content-address substrate, carrying quantum-<strong>shaped</strong> math (the Mermin structure, the σ-reflection, the factored register). &quot;Teleport&quot; is the <strong>two-bit signalling grain</strong> of that encoding, a design mapping — <strong>not</strong> physical quantum teleportation. &quot;Quantum&quot; is the shape and the proofs, <strong>not a device</strong>: the ISO 4879 <strong>3.4.10 device leaf stays open</strong> at <code>/iso-conformance</code> until a CHSH run on real hardware (<code>/chsh-run</code>) returns S &gt; 2. The SDK is complete as a <em>content-address + proof</em> stack; the physical quantum computer is the one evidence still awaited, named and reachable.</p>`,13)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};